// Named Predicates — composable, testable, reusable filter rules
package com.bank.monitor.service;

import com.bank.monitor.model.MonitoredTransaction;
import java.math.BigDecimal;
import java.util.Set;
import java.util.function.Predicate;

public final class FilterRules {

    private FilterRules() {}

    // ═══ LAYER 1: Status ═══
    public static Predicate<MonitoredTransaction> isCompleted() {
        return MonitoredTransaction::isCompleted;
    }

    // ═══ LAYER 2: Amount threshold ═══
    public static Predicate<MonitoredTransaction> amountAbove(BigDecimal threshold) {
        return txn -> txn.getAmount().compareTo(threshold) > 0;
    }

    // ═══ LAYER 3: International ═══
    public static Predicate<MonitoredTransaction> isInternational() {
        return txn -> !"INDIA".equals(txn.getCountry());
    }

    public static Predicate<MonitoredTransaction> isHighRiskCountry(Set<String> countries) {
        return txn -> countries.contains(txn.getCountry());
    }

    // ═══ LAYER 4: New account ═══
    public static Predicate<MonitoredTransaction> isNewAccount(int maxDays) {
        return txn -> txn.getAccountAge() <= maxDays;
    }

    // ═══ COMPOSITE: suspicious = completed AND (large OR international) AND newAccount ═══
    public static Predicate<MonitoredTransaction> suspicious(
            BigDecimal threshold, Set<String> riskCountries, int newAccountDays) {
        return isCompleted()
            .and(amountAbove(threshold).or(isHighRiskCountry(riskCountries)))
            .and(isNewAccount(newAccountDays));
    }

    // ═══ Predicate<? super T> demo — works on any Object ═══
    public static Predicate<Object> notNull() {
        return java.util.Objects::nonNull;
    }
}
