package com.bank.monitor.service;

import com.bank.monitor.dto.MonitorResult;
import com.bank.monitor.model.MonitoredTransaction;
import com.bank.monitor.repository.TransactionRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Predicate;

@Service
@RequiredArgsConstructor
@Slf4j
public class MonitorService {

    private final TransactionRepository txnRepo;

    @Value("${monitoring.min-suspicious-amount:50000}")
    private BigDecimal minAmount;

    @Value("${monitoring.new-account-days:30}")
    private int newAccountDays;

    @Value("${monitoring.high-risk-countries:NIGERIA,CAYMAN,PANAMA}")
    private String riskCountriesCsv;

    // ═══ Layered filter with execution tracking ═══
    @Transactional(readOnly = true)
    public MonitorResult scanWithLayers() {
        List<MonitoredTransaction> all = txnRepo.findAll();
        Set<String> riskCountries = Set.of(riskCountriesCsv.split(","));

        AtomicInteger layer1Count = new AtomicInteger(0);
        AtomicInteger layer2Count = new AtomicInteger(0);
        AtomicInteger layer3Count = new AtomicInteger(0);

        List<String> flagged = all.stream()
            // LAYER 1: filter(isCompleted) — Predicate via method ref
            .filter(txn -> {
                boolean pass = FilterRules.isCompleted().test(txn);
                if (pass) layer1Count.incrementAndGet();
                log.info("  [L1 status] {} → {}", txn.getTxnId(), pass ? "PASS" : "DROP");
                return pass;
            })
            // LAYER 2: filter(amountAbove OR highRisk) — composed Predicate
            .filter(txn -> {
                Predicate<MonitoredTransaction> layer2 =
                    FilterRules.amountAbove(minAmount)
                        .or(FilterRules.isHighRiskCountry(riskCountries));
                boolean pass = layer2.test(txn);
                if (pass) layer2Count.incrementAndGet();
                log.info("  [L2 amount/risk] {} Rs.{} {} → {}",
                    txn.getTxnId(), txn.getAmount(), txn.getCountry(), pass ? "PASS" : "DROP");
                return pass;
            })
            // LAYER 3: filter(isNewAccount) — parameterized Predicate
            .filter(txn -> {
                boolean pass = FilterRules.isNewAccount(newAccountDays).test(txn);
                if (pass) layer3Count.incrementAndGet();
                log.info("  [L3 newAccount] {} age={} → {}",
                    txn.getTxnId(), txn.getAccountAge(), pass ? "PASS (Caution) " : "DROP");
                return pass;
            })
            .map(MonitoredTransaction::getTxnId)
            .toList();

        return new MonitorResult(
            "L1(completed) → L2(amount>" + minAmount + " OR highRisk) → L3(accountAge<" + newAccountDays + "d)",
            all.size(), flagged.size(), flagged,
            Map.of("L1_completed", layer1Count.get() > 0,
                   "L2_amountOrRisk", layer2Count.get() > 0,
                   "L3_newAccount", layer3Count.get() > 0));
    }

    // ═══ Composed Predicate — single filter() call ═══
    @Transactional(readOnly = true)
    public MonitorResult scanComposed() {
        List<MonitoredTransaction> all = txnRepo.findAll();
        Set<String> riskCountries = Set.of(riskCountriesCsv.split(","));

        // ONE composed Predicate replaces 3 separate filter() calls
        Predicate<MonitoredTransaction> suspicious =
            FilterRules.suspicious(minAmount, riskCountries, newAccountDays);

        List<String> flagged = all.stream()
            .filter(suspicious)  // single filter with composed Predicate
            .map(MonitoredTransaction::getTxnId)
            .toList();

        return new MonitorResult(
            "COMPOSED: completed AND (amount>" + minAmount + " OR highRisk) AND newAccount",
            all.size(), flagged.size(), flagged, Map.of());
    }
}
