// ─── File: src/test/java/com/bank/monitor/service/FilterInternalsTest.java ───
package com.bank.monitor.service;

import com.bank.monitor.model.MonitoredTransaction;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Predicate;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class FilterInternalsTest {

    // ═══ filter is LAZY — no execution until terminal ═══
    @Test
    void filterIsLazy() {
        AtomicInteger calls = new AtomicInteger(0);
        Stream<String> pipeline = Stream.of("A", "B", "C")
            .filter(s -> { calls.incrementAndGet(); return true; });

        assertThat(calls.get()).isZero();  // filter NOT called yet!
        pipeline.toList();                  // terminal triggers
        assertThat(calls.get()).isEqualTo(3);
    }

    // ═══ filter is STATELESS — processes one at a time ═══
    @Test
    void filterIsStatelessOneAtATime() {
        List<String> order = new ArrayList<>();

        Stream.of("A", "B", "C").stream()
            .filter(s -> { order.add("filter:" + s); return true; })
            .map(s -> { order.add("map:" + s); return s; })
            .toList();

        // Each element: filter THEN map, before next element
        assertThat(order).containsExactly(
            "filter:A", "map:A",
            "filter:B", "map:B",
            "filter:C", "map:C"
        );
    }

    // ═══ filter accepts Predicate<? super T> ═══
    @Test
    void filterAcceptsSuperTypePredicate() {
        Predicate<Object> notNull = Objects::nonNull;  // Predicate<Object>
        // Can use Predicate<Object> with Stream<String> because Object is super of String
        List<String> result = Stream.of("A", null, "B")
            .filter(notNull)  // Predicate<? super String> accepts Predicate<Object>
            .toList();
        assertThat(result).containsExactly("A", "B");
    }

    // ═══ Predicate composition: and, or, negate ═══
    @Test
    void predicateComposition() {
        Predicate<Integer> above50k = n -> n > 50000;
        Predicate<Integer> below1M = n -> n < 1000000;
        Predicate<Integer> between = above50k.and(below1M);

        assertThat(between.test(75000)).isTrue();
        assertThat(between.test(30000)).isFalse();
        assertThat(between.test(1500000)).isFalse();

        Predicate<Integer> outside = between.negate();
        assertThat(outside.test(30000)).isTrue();
    }

    // ═══ Named Predicates are reusable ═══
    @Test
    void namedPredicatesAreReusable() {
        MonitoredTransaction txn = mock(MonitoredTransaction.class);
        when(txn.isCompleted()).thenReturn(true);
        when(txn.getAmount()).thenReturn(new BigDecimal("1500000"));
        when(txn.getCountry()).thenReturn("NIGERIA");
        when(txn.getAccountAge()).thenReturn(15);

        // Reuse same Predicate across different streams
        Predicate<MonitoredTransaction> suspicious = FilterRules.suspicious(
            new BigDecimal("50000"), Set.of("NIGERIA", "CAYMAN"), 30);

        assertThat(suspicious.test(txn)).isTrue();  // completed + large + highRisk + newAccount
    }

    // ═══ Spliterator drives element traversal ═══
    @Test
    void spliteratorDrivesTraversal() {
        List<String> elements = new ArrayList<>();
        var spliterator = List.of("RELIANCE", "TCS", "HDFC").spliterator();

        // tryAdvance: pull ONE element
        spliterator.tryAdvance(elements::add);
        assertThat(elements).containsExactly("RELIANCE");

        // forEachRemaining: pull ALL remaining
        spliterator.forEachRemaining(elements::add);
        assertThat(elements).containsExactly("RELIANCE", "TCS", "HDFC");
    }
}
